    """
    Implements a regular expression matcher supporting literal characters,
    '.', '*', and '+'. This function uses dynamic programming to build a
    two-dimensional table to track matches as we progress through the pattern
    and text.
    """
    m, n = len(text), len(pattern)
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    dp[0][0] = True

    for j in range(1, n + 1):
        if pattern[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[j - 1] == text[i - 1] or pattern[j - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif pattern[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] if (j > 1 and (pattern[j - 2] == text[i - 1] or pattern[j - 2] == '.')) else False)
            elif pattern[j - 1] == '+':
                dp[i][j] = (dp[i - 1][j] if (j > 1 and (pattern[j - 2] == text[i - 1] or pattern[j - 2] == '.')) else False)

    return dp[m][n]

